import{_ as i,c as a,o as t,ah as e}from"./chunks/framework.Ch_PcVtW.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART0/目次/tmp_context_input.md","filePath":"scripts/output/PART0/目次/tmp_context_input.md"}'),r={name:"scripts/output/PART0/目次/tmp_context_input.md"};function o(s,l,p,S,n,T){return t(),a("div",null,[...l[0]||(l[0]=[e('<p>你是出版项目统筹编辑。</p><p>全局背景信息： 这是一本由日经出版社和bmsg会社合作的连载文集，名为日高光启的管理学，以第一人称的短篇记录形式，结合第三人称的客观介绍，主要跟踪采访了bmsg公司的动向，和日高光启作为ceo和唱跳团体制作人的思考和评价，以及他本人的个人活动，和对行业的一些观点。日高光启本人作为rapper思维活跃，并接受过良好教育，待人平等和蔼，所以本文中语气既有作为专业管理者的一丝不苟和客观严谨，又有作为艺术家和艺术工作者的通情达理、充满激情和想象力。日经出版社作为常年观察bmsg公司动向的出版社，和日高的合作紧密。本书中涉及很多音乐专业和行业特有词汇，如果遇到英文可以保持英文并在括号中注释为常用中文。</p><h2 id="以下是本篇原文" tabindex="-1">以下是本篇原文： <a class="header-anchor" href="#以下是本篇原文" aria-label="Permalink to &quot;以下是本篇原文：&quot;">​</a></h2><p>はじめに</p><h2 id="part1-sky-hi-special-talk" tabindex="-1">PART1: SKY-HI Special Talk <a class="header-anchor" href="#part1-sky-hi-special-talk" aria-label="Permalink to &quot;PART1: SKY-HI Special Talk&quot;">​</a></h2><ul><li>急成長を続ける5年目のBMSG 「社会を善くする」ためのマネジメント</li></ul><h2 id="part2-2023年のbmsg" tabindex="-1">PART2: 2023年のBMSG <a class="header-anchor" href="#part2-2023年のbmsg" aria-label="Permalink to &quot;PART2: 2023年のBMSG&quot;">​</a></h2><ul><li>BE:FIRSTに続くグループMAZZELに込めた「迷路」と「情熱」</li><li>ビジネス系メディアの取材を通じて感じた自信と確信</li><li>BE:FIRST紅白歌合戦出場の意味とAAA時代に感じたこと</li><li>MAZZELを追うドキュメンタリー、エンタテインしない理由</li><li>2つ目のボーイズグループ「MAZZEL」を今作る理由</li><li>「好き=好き」を実現する身体性のために</li><li>BE:FIRSTに課す「大きな夢」のためのマイルストーン</li><li>BMSGを支えるB-Town、その重要性とリニューアルの狙い</li><li>SKY-HIが語るMAZZEL新たなオーディションで目指したもの</li><li>“BMSGに共鳴する仲間”を巻き込むパーティー開催</li><li>BE:FIRSTとMAZZELのリリースを振り返る</li><li>音楽番組『D.U.N.K.』をYouTubeでやる重要性</li><li>ソロのステージで「自分自身」を再定義したかった</li><li>ツアー初日前夜「久しぶりに眠れなかった」理由</li><li>新曲&amp;ドキュメント映画で示すBE:FIRSTの新境地</li><li>メンバーの“音楽的発露”を感じたBE:FIRST最新作</li><li>会社としての仕組みを確立するフェーズに来た</li><li>音楽業界の空気も変えたBMSG、3周年に思うこと</li><li>日本のエンタメを更新したかった2度目の「BMSGFES」</li><li>2度目の「BMSGFES」、EASTとWESTで分けた理由</li><li>【講演】日経クロストレンドFORUM2023より</li><li>続・音楽ビジネス革命</li><li>「嘘がつけない時代」のファンとの関係</li></ul><h2 id="part3-2024年のbmsg" tabindex="-1">PART3: 2024年のBMSG <a class="header-anchor" href="#part3-2024年のbmsg" aria-label="Permalink to &quot;PART3: 2024年のBMSG&quot;">​</a></h2><ul><li>ガールズオーディションはより理想的に歩むための一歩</li><li>Nissyとのコラボ曲で届けたかったテーマとは?</li><li>BMSG設立時からの夢だったNovelCore武道館の意味</li><li>BMSGが発した音楽業界を持続不可能にしないための提言</li><li>初の東京ドーム公演を終えたBE:FIRST、次のフェーズは?</li><li>BE:FIRST東京ドーム公演の演出・選曲に込めた意図</li><li>ずっとやりたかった“本当の意味での音楽番組”がスタート</li><li>法人としてのBMSG、CEOとしての自分の成長を感じた日</li><li>ソロ5人での「BMSG POSSE」を世に出す意図は?</li><li>BE:FIRSTとATEEZのコラボレーションが実現するまで</li><li>デビュー1年で「自己肯定感」と「自尊心」が育ったMAZZEL</li><li>BE:FIRSTの2ndアルバムで社会に見せたかったマインド</li><li>BE:FIRST初の海外公演で感じた大きな手応えと収穫</li><li>夏フェス総括2024カルチャー創造のための必要要件 <br><br></li><li>【講演】日経クロストレンドFORUM 2024より</li><li>続・音楽ビジネス革命</li><li>BMSGの日本再興プラン <br><br></li><li>あとがき <br><br><br><br> 〈初出〉【PART1】書き下ろし【PART2/PART3】日経エンタテインメント!および日経XTREND連載「Be myself,for ourselves」2022年12月~2024年10月掲載分を加筆・修正</li></ul><hr><p>请输出：</p><ol><li>本篇主题与主要内容概述（150~300字）</li><li>人物/术语/语气风险点（要点列出）</li><li>翻译时建议重点</li></ol>',13)])])}const B=i(r,[["render",o]]);export{u as __pageData,B as default};
